/**
 * kiln-dnd's stylesheet is imported for its side effects: `import '@mitcsutt/kiln-dnd/styles.css'`.
 * TypeScript 6 checks side-effect imports, so this declares it; the public entry references
 * this file, so consumers get it with the package's types.
 */
declare module '@mitcsutt/kiln-dnd/styles.css' {}
